LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
use ieee.std_logic_unsigned.all;
library work;
use work.utilities.all;
 
architecture fsm of speed_trap is

   -- Architecture Declarations
   signal timer: std_logic_vector(29 downto 0);
   signal timer_reset: std_logic;
   signal phase: std_logic_vector(1 downto 0);
   signal us_ticker, us_cnt: std_logic_vector(15 downto 0);
   signal us_tick: std_logic;

   type state_type is (
      s_reset,
      s_wait,
      s_ph0a,
      s_ph0b,
      s_ph1a,
      s_ph1b,
      s_ph2a,
      s_ph2b,
      s_ph3a
   );
 
   -- Declare current and next state signals
   signal current_state : state_type;
   signal next_state : state_type;

   -- Declare any pre-registered internal signals
   signal data_rdy_cld : std_logic ;

begin

   -----------------------------------------------------------------
   clocked_proc : process ( 
      clk
   )
   -----------------------------------------------------------------
   begin
      if (clk'event and clk = '1') then
         if (reset = '1') then
            current_state <= s_reset;
            -- Default Reset Values
            data_rdy_cld <= '0';
         else
            current_state <= next_state;
            -- Default Assignment To Internals
            data_rdy_cld <= '0';

            -- Interrupts
            if (speed_trap_en = '0') then
               null;
            else

               -- Combined Actions
               case current_state is
                  when s_wait => 
                     us_cnt <= (others => '0');
                     phase <= "00";
                     if (light_barrier_1 = '1') then 
                        data_rdy_cld <= '1';
                     end if;
                  when s_ph0a => 
                     if us_tick = '1' then
                        us_cnt <= us_cnt + 1;
                     end if;
                  when s_ph0b => 
                     phase <= "01";
                     us_cnt <= (others => '0');
                     if (light_barrier_1 = '0') then 
                        data_rdy_cld <= '1';
                     end if;
                  when s_ph1a => 
                     if us_tick = '1' then
                        us_cnt <= us_cnt + 1;
                     end if;
                  when s_ph1b => 
                     us_cnt <= (others => '0');
                     phase <= "10";
                     if (light_barrier_2 = '1') then 
                        data_rdy_cld <= '1';
                     end if;
                  when s_ph2a => 
                     if us_tick = '1' then
                        us_cnt <= us_cnt + 1;
                     end if;
                  when s_ph2b => 
                     phase <= "11";
                     us_cnt <= (others => '0');
                     if (light_barrier_2 = '0') then 
                        data_rdy_cld <= '1';
                     end if;
                  when s_ph3a => 
                     if us_tick = '1' then
                        us_cnt <= us_cnt + 1;
                     end if;
                  when others =>
                     null;
               end case;
            end if;
         end if;
      end if;
   end process clocked_proc;
 
   -----------------------------------------------------------------
   nextstate_proc : process ( 
      current_state,
      guard_time,
      light_barrier_1,
      light_barrier_2,
      speed_trap_en,
      us_cnt
   )
   -----------------------------------------------------------------
   begin

      -- Interrupts
      if (speed_trap_en = '0') then
         next_state <= s_wait;
      else
         case current_state is
            when s_reset => 
               next_state <= s_wait;
            when s_wait => 
               if (light_barrier_1 = '1') then 
                  next_state <= s_ph0a;
               else
                  next_state <= s_wait;
               end if;
            when s_ph0a => 
               if (us_cnt = guard_time) then 
                  next_state <= s_ph0b;
               else
                  next_state <= s_ph0a;
               end if;
            when s_ph0b => 
               if (light_barrier_1 = '0') then 
                  next_state <= s_ph1a;
               else
                  next_state <= s_ph0b;
               end if;
            when s_ph1a => 
               if (us_cnt = guard_time) then 
                  next_state <= s_ph1b;
               else
                  next_state <= s_ph1a;
               end if;
            when s_ph1b => 
               if (light_barrier_2 = '1') then 
                  next_state <= s_ph2a;
               else
                  next_state <= s_ph1b;
               end if;
            when s_ph2a => 
               if (us_cnt = guard_time) then 
                  next_state <= s_ph2b;
               else
                  next_state <= s_ph2a;
               end if;
            when s_ph2b => 
               if (light_barrier_2 = '0') then 
                  next_state <= s_ph3a;
               else
                  next_state <= s_ph2b;
               end if;
            when s_ph3a => 
               if (us_cnt = guard_time) then 
                  next_state <= s_wait;
               else
                  next_state <= s_ph3a;
               end if;
            when others =>
               next_state <= s_reset;
         end case;
      end if;
   end process nextstate_proc;
 
   -----------------------------------------------------------------
   output_proc : process ( 
      current_state,
      speed_trap_en
   )
   -----------------------------------------------------------------
   begin
      -- Default Assignment To Internals
      timer_reset <= '0';

      -- Interrupts
      if (speed_trap_en = '0') then
         null;
      else

         -- Combined Actions
         case current_state is
            when s_wait => 
               timer_reset <= '1';
            when others =>
               null;
         end case;
      end if;
   end process output_proc;
 
   -- Concurrent Statements
   -- Clocked output assignments
   data_rdy <= data_rdy_cld;
   -- write measurement phase and timer to FIFO -----
   data <= phase & timer;
   
   ---- timer for measurement -------
   process(clk)
   begin
   if rising_edge(clk) then
      if timer_reset = '1' then
          timer <= (others => '0');
      else
          timer <= timer + 1;
      end if;
   end if;
   end process;
   
   ---- usec ticker for guard time to de-bounce light barrier transitions -------
   process(clk)
   begin
   if rising_edge(clk) then
      if reset = '1' then
          us_ticker <=  (others => '0');
      else
          if us_tick = '1' then
              us_ticker <=  (others => '0');
          else
              us_ticker <= us_ticker + 1;
          end if;
      end if;
   end if;
   end process;
   
   ---assume 100MHz core clock-----
   us_tick <= '1' when us_ticker = 99 else '0';
   
   --- state output for debugging ---
   process(clk)
   begin
      if rising_edge(clk) then
         if phase = "00" then
               state <= "0001";
         elsif phase = "01" then
               state <= "0010";
         elsif phase = "10" then
                state <= "0100";
         else
                state <= "1000";
         end if;
      end if;
   end process;
end fsm;
